# apply-animations.ps1
# Run from D:\alltix-oms-review (repo root). Idempotent: safe to re-run.
$ErrorActionPreference = "Stop"

function Sync-B64File($relPath, $b64) {
  $full = Join-Path (Get-Location) $relPath
  $dir = Split-Path $full -Parent
  if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
  $bytes = [Convert]::FromBase64String(($b64 -replace "\s",""))
  if (Test-Path $full) {
    $existing = [IO.File]::ReadAllBytes($full)
    if ([BitConverter]::ToString($existing) -eq [BitConverter]::ToString($bytes)) {
      Write-Host "Already up to date: $relPath"
      return
    }
  }
  [IO.File]::WriteAllBytes($full, $bytes)
  Write-Host "Wrote $relPath ($($bytes.Length) bytes)"
}

function Append-Once($relPath, $marker, $b64Block) {
  $full = Join-Path (Get-Location) $relPath
  $content = Get-Content -Raw -LiteralPath $full
  if ($content.Contains($marker)) {
    Write-Host "Already appended: $relPath"
    return
  }
  $bytes = [Convert]::FromBase64String(($b64Block -replace "\s",""))
  $blockText = [Text.Encoding]::UTF8.GetString($bytes)
  $updated = $content.TrimEnd("`r", "`n") + "`n`n" + $blockText
  [IO.File]::WriteAllText($full, $updated)
  Write-Host "Appended animation CSS to $relPath"
}

# --- 1. New scroll-reveal component ---

$b64ScrollReveal = @'

'@
Sync-B64File "packages/web/src/components/marketing/scroll-reveal.tsx" $b64ScrollReveal

# --- 2. Wire it into the marketing layout ---

$b64Layout = @'

'@
Sync-B64File "packages/web/src/app/(marketing)/layout.tsx" $b64Layout

# --- 3. Reveal/hover-lift/mobile-menu animation CSS ---

$b64AnimCss = @'

'@
Append-Once "packages/web/src/app/(marketing)/marketing.module.css" "ANIMATIONS" $b64AnimCss

Write-Host ""
Write-Host "Done. Review with 'git status' / 'git diff', then commit and push."
